/**
 * Marks free text written by store owners or imported from their files, so the model reads it as
 * catalog data and not as instructions.
 */
const TAG = /<\s*\/?\s*store_data\s*>/gi;

/** Keys whose values are generated by the server or are identifiers, not owner text. */
const GENERATED_KEY =
  /(^id$|^date$|_id$|_at$|url$|^status$|^currency$|^price|^availability|_label$|^can_order$|^source$|^kind$|^error$|^code$|^total$|^quantity$|^size$)/i;

export function stripStoreDataTags(text: string): string {
  let previous: string;
  let current = text;
  do {
    previous = current;
    current = current.replace(TAG, "");
  } while (current !== previous);
  return current;
}

export function markStoreData(text: string): string {
  return `<store_data>${stripStoreDataTags(text)}</store_data>`;
}

function walk(value: unknown, key: string): unknown {
  if (typeof value === "string") {
    return value.trim() === "" || GENERATED_KEY.test(key) ? value : markStoreData(value);
  }
  if (Array.isArray(value)) return value.map((item) => walk(item, key));
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([name, item]) => [name, walk(item, name)]),
    );
  }
  return value;
}

/** Wraps the owner-written strings of a JSON tool result; other text is returned unchanged. */
export function wrapStoreData(text: string): string {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return text;
  }
  if (parsed === null || typeof parsed !== "object") return text;
  return JSON.stringify(walk(parsed, ""), null, 2);
}
